/** Compact Host workflow generated by `stetra init`. */

import { hostAdapterDefinition, type HostAdapter } from './definition.ts';
import { taskInputExample } from '../schemas/task-input.ts';

export type { HostAdapter } from './definition.ts';

export function renderHostSkill(adapter: HostAdapter): string {
  const host = hostAdapterDefinition(adapter).displayName;
  return `---
name: stetra
description: Preserve developer understanding and adoption authority for an admitted coding change.
---

# Stetra

Use normal conversation and ${host}'s engineering loop. Call the CLI with \`--json\`.
Replace TASK_ID below with Begin's taskId; pass \`--task\` to collect,
handoff, inspect, and decide.

## Admit and align

Follow the SessionStart admission policy. Conversation-only work and declined
tasks create no task. For an admitted task, call \`stetra task begin\` before
editing. Routine is the default; consequential assurance requires an explicit
Human choice or project policy. Replace this example with the exact request,
your interpretation, and actual repository checks:

\`\`\`sh
stetra task begin --input - --json <<'JSON'
${taskInputExample('begin')}
JSON
\`\`\`

Use stdin (\`--input -\`) or a file outside the project worktree. Query
\`stetra task begin --input-schema --json\` for profile, no-command, or
consequential input.

Pass the Hook's opaque \`--binding-token\` only to \`task begin\`. Do not
read or edit canonical task files. Relay Human text byte-for-byte; this thin
adapter records unattested input and cannot attest native prompt identity.

## Work

Implement normally. When the implementation is ready, call \`stetra task
collect\` once. If a frozen Check is not passing, use its exact result and
bounded log as ordinary engineering feedback, repair normally, and collect
again. Only an actual timeout may be retried by calling task collect with
--retry-timeout <check-key> and --timeout-ms <larger-ms>, within the returned
bound. No Stetra diagnosis document is required.
After a non-timeout external failure, an available \`failureRefresh\` allows
one explicit \`task collect --refresh-reason <reason>\` for unchanged inputs.
The reason is your judgment; Runtime preserves both observed results.

## Decide

After current facts exist, call \`stetra task handoff\` with actual behavior,
mechanism, and your evidence-bounded recommendation:

\`\`\`sh
stetra task handoff --task TASK_ID --input - --json <<'JSON'
${taskInputExample('handoff')}
JSON
\`\`\`

Use \`stetra task handoff --input-schema --json\` for optional unknowns,
invariants, failure paths, effects, tradeoffs, and review focus. Describe material
review questions with their consequence, a concrete next action, and a changed
path or Check key. Passing checks do not establish semantic coverage by themselves.
Routine Handoff omits \`concernFindings\`. Consequential findings use only
the concern keys declared at Begin.

Present the returned \`decisionBrief\`, state that adoption is pending, ask the
developer to accept, request correction, reject, or defer, and stop. Only a new
developer message may be passed to \`stetra task decide\`. Acceptance with
Attention requires the developer to explicitly acknowledge it.
Use \`stetra task decide --input-schema --json\` for the decision input.
Restore the complete current brief through \`task inspect --section handoff\`;
if facts are stale, collect and author a new Handoff first. Task corrections are
available in \`task inspect --section summary\`. After a task closes, a later
admitted coding task can use the same session binding token.

Keep Runtime facts, Agent judgment, and Human authority distinct. Preserve
adverse evidence; passing checks are observations, not adoption.
`;
}

export function renderHostPointerBlock(
  adapter: HostAdapter,
  markers: { start: string; end: string },
): string {
  const skillPath = `${hostAdapterDefinition(adapter).skillRoot}/SKILL.md`;
  return `${markers.start}
For an admitted Agent-authored coding change, follow [the generated Stetra skill](${skillPath}).
${markers.end}`;
}
